Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  runApp(const ProviderScope(child: DoseGrindApp()));
}

class DoseGrindApp extends ConsumerStatefulWidget {
  const DoseGrindApp({super.key});
  @override ConsumerState<DoseGrindApp> createState() => _DoseGrindAppState();
}
class _DoseGrindAppState extends ConsumerState<DoseGrindApp> {
  @override void initState() { super.initState(); Future.microtask(() => ref.read(appStateProvider).initialize()); }
  @override Widget build(BuildContext context) => MaterialApp(
    title: 'DoseGrind Connect', debugShowCheckedModeBanner: false,
    theme: ThemeData(useMaterial3: true, colorScheme: ColorScheme.fromSeed(seedColor: leaf, brightness: Brightness.light, surface: cream), scaffoldBackgroundColor: cream, fontFamily: 'Roboto', appBarTheme: const AppBarTheme(backgroundColor: cream, foregroundColor: ink), cardTheme: CardThemeData(color: Colors.white, elevation: 0, shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(22))), navigationBarTheme: const NavigationBarThemeData(backgroundColor: cream, indicatorColor: lime)),
    home: const MainShell(),
  );
}

class MainShell extends ConsumerStatefulWidget { const MainShell({super.key}); @override ConsumerState<MainShell> createState()=>_MainShellState(); }
class _MainShellState extends ConsumerState<MainShell> {
 int index=0;
 @override Widget build(BuildContext context) {
  final app=ref.watch(appStateProvider);
  final pages=<Widget>[
   HomeScreen(onOpenRecipes:()=>setState(()=>index=1), onOpenHistory:()=>setState(()=>index=2)),
   RecipesScreen(), HistoryScreen(), GuideScreen(),
  ];
  return Scaffold(body: SafeArea(child: pages[index]), bottomNavigationBar: NavigationBar(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),destinations: const [NavigationDestination(icon:Icon(Icons.grid_view_rounded),label:'Overview'),NavigationDestination(icon:Icon(Icons.menu_book_rounded),label:'Recipes'),NavigationDestination(icon:Icon(Icons.history_rounded),label:'History'),NavigationDestination(icon:Icon(Icons.tune_rounded),label:'Guide')]));
 }
}

